#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int, int>>> adj(n + 1);   // (비용, 정점)
    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({w, v});
        adj[v].push_back({w, u});
    }
    // greater 를 줘야 가장 싼 간선이 top 에 와요 (기본은 최대 힙)
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    vector<bool> visited(n + 1, false);
    pq.push({0, 1});
    long long total = 0;
    int cnt = 0;
    while (!pq.empty()) {
        auto [w, v] = pq.top();
        pq.pop();
        if (visited[v]) continue;
        visited[v] = true;
        total += w;
        cnt++;
        for (auto [nw, nv] : adj[v])
            if (!visited[nv]) pq.push({nw, nv});
    }
    if (cnt == n) cout << total << "\n";
    else cout << "연결되지 않음\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<pair<long long, long long>> pts = {{0, 0}, {2, 0}, {2, 3}, {5, 1}, {6, 4}};
    int n = pts.size();
    const long long INF = LLONG_MAX;
    vector<long long> dist(n, INF);   // 지금 트리에 붙이는 가장 싼 비용
    vector<bool> used(n, false);
    dist[0] = 0;
    long long total = 0;
    for (int step = 0; step < n; step++) {
        int v = -1;
        for (int i = 0; i < n; i++)   // 최솟값 찾기 O(N)
            if (!used[i] && (v == -1 || dist[i] < dist[v])) v = i;
        used[v] = true;
        total += dist[v];
        for (int i = 0; i < n; i++) { // 새 정점 기준으로 갱신 O(N)
            if (used[i]) continue;
            long long dx = pts[i].first - pts[v].first, dy = pts[i].second - pts[v].second;
            dist[i] = min(dist[i], dx * dx + dy * dy);
        }
    }
    cout << total << "\n";
    return 0;
}

